function buildQuestions(subject, topic, entries, startIndex = 0) {
  return entries.map(([question, answer, distractors, correct, level, explanation], index) => {
    const options = [...distractors];
    options.splice(correct, 0, answer);
    return {
      id: `topic-${subject}-${topic}-${startIndex + index + 1}`,
      question,
      options,
      correct,
      level,
      explanation,
    };
  });
}

